// 生产者发送消息
channel.confirmSelect(); // 开启确认模式
channel.basicPublish(exchange, routingKey, props, message);
channel.addConfirmListener(
    (deliveryTag, multiple) -> log.info("确认: {}", deliveryTag),
    (deliveryTag, multiple) -> log.error("nack: {}", deliveryTag)
);

// 消费者手动确认
channel.basicConsume(queue, false, (tag, delivery) -> {
    try {
        // 处理消息
        processMessage(delivery.getBody());
        channel.basicAck(delivery.getEnvelope().getDeliveryTag(), false);
    } catch (Exception e) {
        channel.basicNack(delivery.getEnvelope().getDeliveryTag(), false, true);
    }
});

// 死信队列配置
// 声明死信交换机和队列
channel.exchangeDeclare("dlx.exchange", "direct");
channel.queueDeclare("dlx.queue", true, false, false, null);
channel.queueBind("dlx.queue", "dlx.exchange", "dlx.routingkey");
// 原队列绑定死信交换机
Map<String, Object> args = new HashMap<>();
args.put("x-dead-letter-exchange", "dlx.exchange");
args.put("x-dead-letter-routing-key", "dlx.routingkey");
channel.queueDeclare("normal.queue", true, false, false, args);
